allowed_counts = []
for c1 in range(31):
    for c2 in range(31 - c1):
        c3 = 30 - c1 - c2
        if (c1 == c2 + 6 or c2 == c1 + 6 or c1 == c3 + 6 or c3 == c1 + 6 or c2 == c3 + 6) and max(c1,c2,c3) >= 2:
            allowed_counts.append((c1,c2,c3))

def minpay_for_guess(g):
    minp = float('inf')
    worst_c = None
    for c in allowed_counts:
        # host chooses ordering of counts to minimize sum; we need to compute minimal sum over permutations
        # compute minimal sum by assigning counts to guess optimally: we can try all permutations of indices (3! =6)
        import itertools
        best_perm = float('inf')
        for perm in itertools.permutations(c):
            payoff = sum(g_i if g_i <= c_i else 0 for g_i, c_i in zip(g, perm))
            if payoff < best_perm:
                best_perm = payoff
        if best_perm < minp:
            minp = best_perm
            worst_c = perm
    return minp, worst_c

